import html
BASE="https://tuanbui1.github.io/mattress-disposal-directory/"
NAME="Bulky Item Disposal Guide"
CSS="""*{box-sizing:border-box}body{font:16px/1.6 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;margin:0;color:#1d2433;background:#f7f8fa}
header,main,footer{max-width:820px;margin:auto;padding:16px}header{border-bottom:1px solid #dde}header a{color:#1d2433;text-decoration:none;font-weight:700}
h1{font-size:1.7rem;line-height:1.25}h2{font-size:1.2rem;margin-top:1.8em;border-top:1px solid #e3e6ec;padding-top:1em}a{color:#0b5cad}
.note{background:#fff8e1;border-left:4px solid #e0a800;padding:10px 14px;font-size:.92rem}.unv{background:#fdecea;border-left:4px solid #c62828;padding:8px 12px;font-size:.92rem}
.widget{border:2px dashed #9aa5b5;padding:20px;text-align:center;color:#5a6577;border-radius:8px;background:#fff}
ul.cities{list-style:none;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px}ul.cities a{display:block;background:#fff;padding:14px;border-radius:8px;border:1px solid #dde;text-decoration:none}
sup a{text-decoration:none;font-size:.75rem}ol.src{font-size:.85rem;word-break:break-all}footer{font-size:.85rem;color:#5a6577;border-top:1px solid #dde}"""
DISC="<p><strong>Disclaimer:</strong> This is an independent informational guide, not affiliated with any city, state, or company. Rules and fees change; always confirm with the official source linked before acting. Last checked Oct 2026.</p>"
def page(path,title,desc,body):
    canon=BASE+path
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><link rel="canonical" href="{canon}">
<meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{canon}">
<style>{CSS}</style></head><body><header><a href="./">{NAME}</a></header><main>{body}</main><footer>{DISC}</footer><script data-goatcounter="https://bulkydisposal.goatcounter.com/count" async src="//gc.zgo.at/count.js"></script></body></html>"""
WIDGET='<h2>Book a paid hauler</h2><p>If city service doesn\'t fit (too many items, large building, timing), a private junk-removal or mattress-recycling hauler is the fallback. Ask that they recycle the mattress.</p><div class="widget" id="hauler-widget"><!-- HAULER BOOKING WIDGET PLACEHOLDER -->Hauler booking widget coming soon.</div>'
MA_BAN=("<p>Massachusetts bans mattresses (including box springs and foundations) and textiles from disposal or transport for disposal, effective November 1, 2022{c0}. Mattresses contaminated with mold, bodily fluids, insects, oil, or hazardous substances are excluded from the ban's definition{c1}. Textiles covered include clothing, footwear, bedding, towels, curtains and fabric — even worn or stained items can go to textile recovery{c1}{c2}.</p>")
MA_SRC=["https://www.mass.gov/guides/massdep-waste-disposal-bans","https://www.mass.gov/doc/frequently-asked-questions-mattress-textile-waste-ban/download","https://www.mass.gov/guides/clothing-and-textile-recovery"]
BBM=("<p><strong>Bye Bye Mattress:</strong> the Mattress Recycling Council's Bye Bye Mattress program currently runs only in California, Connecticut, Oregon and Rhode Island{c}, so it does not operate in this state.</p>")
BBM_SRC="https://mattressrecyclingcouncil.org/about/"
cities=[]
def city(slug,name,desc,sections,srcs,unverified):
    def c(i): return f'<sup><a href="#s{i+1}">[{i+1}]</a></sup>'
    body=f"<h1>How to dispose of a mattress in {name}</h1><p class='note'>Last checked Oct 2026. Every fact below links to an official source; confirm before acting.</p>"
    for h,t in sections: body+=f"<h2>{h}</h2>"+t(c)
    if unverified: body+="<h2>Not yet verified</h2><div class='unv'><ul>"+"".join(f"<li>{u}</li>" for u in unverified)+"</ul></div>"
    body+=WIDGET+"<h2>Sources</h2><ol class='src'>"+"".join(f'<li id="s{i+1}"><a href="{u}" rel="nofollow">{u}</a></li>' for i,u in enumerate(srcs))+"</ol><p><a href='./'>&larr; All cities</a></p>"
    open(slug+".html","w").write(page(slug+".html",f"Mattress & Bulky Item Disposal in {name} (2026) | {NAME}",desc,body))
    cities.append((slug,name))

# Boston: srcs 0 boston mattress,1 large bldgs,2 trash,3-5 MA,6 MRC
city("boston-ma","Boston, MA","How to get rid of a mattress or box spring in Boston: appointment pickup, bag rules, 10-item yearly limit, state ban and recyclers. Official sources.",[
("Curbside pickup &amp; scheduling",lambda c:f"<ul><li>Boston requires an appointment for every mattress and box spring; they are not collected with curbside trash{c(0)}. Schedule online on the city's Mattress Recycling page, or contact 311 / 617-635-4500{c(0)}.</li><li>City pickup is only for buildings with six units or fewer; larger buildings must go through the property manager or a mattress recycling hauler{c(0)}{c(1)}.</li><li>Place it curbside by 6 a.m. on your appointment day, or after 5 p.m. the night before, where trash is normally collected — not on private property, not blocked, nothing on top, not crushed or cut{c(0)}.</li><li>Cancel before 12 p.m. the day before; report missed pickups to 311 within 24 hours{c(0)}.</li><li>Accepted: memory foam, box spring, innerspring, hybrid, latex. Not accepted: futons, toppers and similar (those may go out with curbside trash){c(0)}.</li><li>Furniture can go out with normal curbside trash on collection day; appliances (fridges, TVs, ACs) must be requested through 311{c(2)}.</li></ul>"),
("Mattress bag requirements",lambda c:f"<p>Soiled, dirty, or bed-bug mattresses must be bagged and fully sealed; bags are sold at hardware stores or online. Bagging is also suggested in bad weather{c(0)}.</p>"),
("Fees &amp; limits",lambda c:f"<p>Limit: 10 items per calendar year{c(0)}. The city page does not list a fee for eligible residents{c(0)}.</p>"),
("Massachusetts disposal ban",lambda c:MA_BAN.format(c0=c(3),c1=c(4),c2=c(5))),
("Drop-off &amp; recycling",lambda c:f"<p>The city lists private recyclers for large buildings, e.g. HandUp Mattress Recycling (drop-off $35/item), Green Mattress (Brockton drop-off), Raw Material Recovery (Gardner drop-off), Tough Stuff Recycling ($25 drop-off / $75 pickup){c(1)}. No city-run mattress drop-off site was found on the city pages checked.</p>"+BBM.format(c=c(6))),
("Retailer take-back",lambda c:f"<p>The city advises asking your mattress seller whether they will take the old mattress for recycling at delivery{c(0)}. Specific retailer programs are not verified here.</p>"),
],["https://www.boston.gov/departments/public-works/mattress-recycling","https://www.boston.gov/departments/public-works/large-residential-buildings","https://content.boston.gov/departments/public-works/trash"]+MA_SRC+[BBM_SRC],
["Whether any fee applies to eligible residents (none listed on the city page).","Hauler prices are as listed by the city, not confirmed with the companies."])

city("somerville-ma","Somerville, MA","Somerville mattress disposal: $55 sticker, 311 scheduling, curb times, 2-item weekly limit, Massachusetts ban. Official sources.",[
("Curbside pickup &amp; scheduling",lambda c:f"<ul><li>Eligible: households in buildings with 6 or fewer units receiving City trash collection; larger buildings with private service should ask their building manager{c(0)}.</li><li>Buy a Disposal Sticker first, then contact 311 (617-666-3311 or somervillema.gov/311) no later than 3:30 p.m. the day before collection{c(0)}.</li><li>Pickup is one day after your regular trash day (Friday trash households: Friday). Put items out from 4 p.m. the day before, by 7 a.m. pickup day, leaving a 36-inch clear sidewalk path{c(0)}.</li><li>Unscheduled mattresses put out with trash will be left and may be fined{c(0)}.</li><li>Furniture: City picks up two pieces per week with trash{c(2)}.</li></ul>"),
("Mattress bag requirements",lambda c:f"<p>If soiled or bed-bug infested, call 311 for special instructions before buying a sticker{c(0)}. Bed-bug infested items must be wrapped in plastic and clearly marked{c(2)}.</p>"),
("Fees &amp; limits",lambda c:f"<ul><li>$55 Disposal Sticker per item (mattress and box spring each need one), since Feb 1, 2026{c(0)}{c(1)}.</li><li>Buy online (somervillema.gov/payonline; mail can take up to 10 days), at DPW, One Franey Road (no cash), or City Clerk, 93 Highland Ave{c(0)}.</li><li>Limit: two bulk items (including mattresses/box springs) per week{c(0)}.</li></ul>"),
("Massachusetts disposal ban",lambda c:MA_BAN.format(c0=c(3),c1=c(4),c2=c(5))),
("Drop-off &amp; recycling",lambda c:"<p>No city mattress drop-off site was found on the city pages checked.</p>"+BBM.format(c=c(6))),
("Retailer take-back",lambda c:"<p>Not verified from an official Somerville source.</p>"),
],["https://www.somervillema.gov/mattressrecycling","https://www.somervillema.gov/news/somerville-introduces-mattress-recycling-fee-program","https://www.somervillema.gov/trash-and-recycling"]+MA_SRC+[BBM_SRC],
["Retailer take-back options.","Any city drop-off option for mattresses."])

city("chelsea-ma","Chelsea, MA","Chelsea MA mattress pickup: $25/$40 sticker, Monday & Thursday collection via 311, plastic wrap required, Massachusetts ban. Official sources.",[
("Curbside pickup &amp; scheduling",lambda c:f"<ul><li>Mattress collection days are Monday and Thursday. Pay, get your collection sticker, then call 311 (617-466-4209) to schedule{c(0)}.</li><li>Leave the mattress outside by 7 a.m. on the scheduled day with the sticker attached; unscheduled mattresses may be ticketed. Tell 311 if it has bed bugs{c(0)}.</li><li>Mattresses and box springs are not accepted in regular trash; furniture is limited to 2 items per week with trash{c(2)}.</li></ul>"),
("Mattress bag requirements",lambda c:f"<p>Mattress must be wrapped in plastic{c(0)}; items not wrapped will not be collected and may get a citation{c(3)}.</p>"),
("Fees &amp; limits",lambda c:f"<ul><li>City trash customers: $25 per mattress/box spring (since Feb 1, 2026){c(0)}{c(1)}.</li><li>Private-hauler customers: ask your hauler first; otherwise the City charges $40 per item{c(0)}.</li><li>Pay at City Hall, online (\"Apply For A Permit\" → \"Curbside Mattress Pick Up\"), or by check to 500 Broadway, Room 310{c(0)}.</li><li>Illegal dumping fines: $50 / $150 / $300{c(1)}.</li></ul>"),
("Massachusetts disposal ban",lambda c:MA_BAN.format(c0=c(4),c1=c(5),c2=c(6))+f"<p>Chelsea offers free curbside textile pickup on Sundays via 311 or helpsy.co/chelseama{c(7)}.</p>"),
("Drop-off &amp; recycling",lambda c:"<p>No city mattress drop-off site was found on the city pages checked.</p>"+BBM.format(c=c(8))),
("Retailer take-back",lambda c:"<p>Not verified from an official Chelsea source.</p>"),
],["https://www.chelseama.gov/departments/public_works/trash,_recycle,___yard_waste/disposal_regulations/mattress_recycling.php","https://www.chelseama.gov/news_detail_T2_R761.php","https://chelseama.gov/departments/public_works/trash,_recycle,___yard_waste/disposal_regulations/trash.php","https://www.chelseama.gov/departments/public_works/trash,_recycle,___yard_waste/billing___fees/index.php"]+MA_SRC+["https://www.chelseama.gov/departments/public_works/trash,_recycle,___yard_waste/index.php",BBM_SRC],
["Retailer take-back options.","Per-week limit on mattresses (only furniture limit found)."])

city("new-york-city","New York City, NY","NYC mattress disposal: free DSNY curbside collection, sealed plastic bag rule, 6 items per day, fines. Official DSNY & 311 sources.",[
("Curbside pickup &amp; scheduling",lambda c:f"<ul><li>DSNY collects large items free at the curb; appointments are no longer offered or needed{c(0)}{c(1)}.</li><li>Mattresses and box springs go out on your trash-only day, not recycling day{c(2)}, curbside between 6 PM and midnight the night before{c(3)}.</li><li>Not in the street, in front of another property, blocking pedestrians, or on private property{c(1)}.</li></ul>"),
("Mattress bag requirements",lambda c:f"<p>Must be fully enclosed in a securely sealed plastic bag to prevent bed bugs{c(4)}. 311 says bags can be any color except red or orange and the City does not provide them; buy at department, home improvement, or moving supply stores{c(3)}. (Note: DSNY's Collection Laws page says a <em>clear</em> plastic bag{c(4)} — when in doubt use clear.)</p>"),
("Fees &amp; limits",lambda c:f"<ul><li>Collection is free; up to 6 bulk items per collection day{c(0)}.</li><li>Fines for improper mattress disposal: $50 / $100 / $200{c(4)}{c(3)}; DSNY's item page says up to $300{c(2)}.</li></ul>"),
("State disposal ban",lambda c:"<p>No New York State mattress disposal ban was found in the official sources checked; not verified.</p>"),
("Drop-off &amp; recycling",lambda c:BBM.format(c=c(5))+"<p>City drop-off options for mattresses: not verified.</p>"),
("Retailer take-back",lambda c:"<p>Not verified from an official NYC source.</p>"),
],["https://www.nyc.gov/site/dsny/collection/get-rid-of/large-items.page","https://portal.311.nyc.gov/article/?kanumber=KA-01969","https://www.nyc.gov/site/dsny/collection/get-rid-of/furniture-mattresses.page","https://portal.311.nyc.gov/article/?kanumber=KA-02378","https://www.nyc.gov/site/dsny/collection/residents/collection-laws-residents.page",BBM_SRC],
["Bag color: 311 says any color except red/orange; DSNY law page says clear.","Fine amounts differ between DSNY pages ($200 max vs up to $300).","Whether NY State has any mattress disposal ban.","Retailer take-back and drop-off sites."])

city("chicago-il","Chicago, IL","Chicago mattress and bulky item disposal: who the city serves, 311 requests, and what's unverified. Official sources.",[
("Curbside pickup &amp; scheduling",lambda c:f"<p>City crews collect from single-family homes and buildings of four units or less; others must arrange private collection{c(0)}{c(1)}. The city lists a \"Non-Scheduled Garbage\" service{c(0)}; request city services through 311 / CHI311{c(2)}.</p>"),
("Mattress bag requirements",lambda c:"<p>Not verified: we could not load the official CHI311 bulk-pickup article this check.</p>"),
("Fees &amp; limits",lambda c:"<p>Not verified.</p>"),
("State disposal ban",lambda c:"<p>No Illinois mattress disposal ban was found in the official sources checked; not verified.</p>"),
("Drop-off &amp; recycling",lambda c:BBM.format(c=c(3))+"<p>City drop-off options: not verified.</p>"),
("Retailer take-back",lambda c:"<p>Not verified.</p>"),
],["https://www.chicago.gov/city/en/depts/streets/supp_info/residential_garbage.html","https://www.chicago.gov/city/en/depts/streets/provdrs/streets_san/svcs/residential_garbagecollection.html","https://311.chicago.gov/",BBM_SRC],
["Exact bulk/mattress set-out rules, bagging, limits and fees (CHI311 article returned 503).","Illinois state ban status.","Drop-off sites and retailer take-back."])
city("los-angeles-ca","Los Angeles, CA","Los Angeles mattress disposal: free unlimited LASAN bulky item pickup, how to schedule, monthly drop-off days, California retailer take-back and Bye Bye Mattress. Official sources.",[
("Curbside pickup &amp; scheduling",lambda c:f"<ul><li>LA Sanitation &amp; Environment (LASAN) picks up mattresses and box springs as bulky items; it is an unlimited curbside service at no additional charge{c(0)}.</li><li>Pickup happens on your regular trash day, and you must request it at least one business day before your normal collection{c(0)}.</li><li>Schedule online (LASAN service request form), in the MyLA311 app, or by calling the 24-hour Customer Care Center at 1-800-773-2489{c(0)}. You can also dial 311 or (213) 473-3231{c(1)}.</li><li>Have an itemized list ready (for example, \"one mattress, two chairs\") so the right-sized truck is sent{c(0)}.</li><li>Mattresses and other bulky items do not go in the black trash bin{c(2)}.</li><li>Also accepted at the curb: furniture, toilets and sinks, carpet (rolled and tied), large wood or doors{c(0)}. Not accepted: auto parts or oil, construction materials, commercial appliances, paints or chemicals, medicines or needles, fluorescent lights{c(0)}.</li></ul>"),
("Mattress bag requirements",lambda c:"<p>The LASAN bulky item page checked does not mention a bagging requirement for mattresses. Not verified.</p>"),
("Fees &amp; limits",lambda c:f"<p>No additional charge and no item limit for curbside bulky pickup, per LASAN{c(0)}.</p>"),
("California mattress program &amp; retailer take-back",lambda c:f"<p>California's Mattress Stewardship Program, overseen by CalRecycle and run by the Mattress Recycling Council (MRC), covers used mattresses, box springs and futons{c(3)}.</p><p>If a new mattress is delivered, California law requires the retailer to offer to take back your old one at no additional cost; delivery fees may still apply, the retailer has up to 30 days, and may refuse a mattress that poses a health or safety risk (as summarized by MRC's Bye Bye Mattress){c(4)}.</p>"),
("Drop-off &amp; recycling",lambda c:f"<ul><li><strong>City drop-off days:</strong> LASAN runs free bulky item drop-off on one Saturday a month, 8:00 a.m. to 4:30 p.m. Remaining 2026 dates: Nov 21 and Dec 12{c(0)}{c(5)}.</li><li>Locations: East Valley, 11050 Pendelton St., Sun Valley; West Valley, 8840 Vanalden Ave., Northridge; Harbor, 1400 N. Gaffey St., San Pedro; West LA, 2027 Stoner Ave.; Central LA, 2201 E. Washington Blvd.{c(0)}</li><li>Mattresses, box springs, futons and headboards are on the accepted list. You must be present with your most current LADWP bill and a state driver's license or ID; one visit per event; vehicles up to a flat/stake-bed truck{c(5)}.</li><li><strong>Bye Bye Mattress:</strong> California is an MRC program state, with no-cost drop-off at participating locations; use the locator on its California page and contact the site first{c(4)}{c(6)}.</li></ul>"),
],["https://sanitation.lacity.gov/services/schedule-bulky-item-pickup","https://lacity.gov/myla311","https://sanitation.lacity.gov/services/weekly-curbside-black-bin-collection-trash","https://calrecycle.ca.gov/mattresses/","https://byebyemattress.com/california/","https://sanitation.lacity.gov/media/866",BBM_SRC],
["Eligibility for apartment buildings: the LASAN page is labeled for single-family residents; multi-unit rules were not checked.","Whether mattresses must be bagged or wrapped.","Electronics: the LASAN page lists e-waste as accepted but also defines bulky items as non-electronic; confirm with LASAN.","Whether California has a mattress landfill disposal ban (none found in sources checked)."])

city("houston-tx","Houston, TX","Houston mattress disposal: free heavy trash curbside pickup every other month, set-out rules, 8 cubic yard limit, and six free Residential Drop-Off Centers. Official City of Houston sources.",[
("Curbside heavy trash pickup",lambda c:f"<ul><li>Mattresses and box springs are accepted in Houston's curbside Heavy Trash collection{c(0)}.</li><li>Heavy trash is collected every other month, in even-numbered months (February, April, June, August, October, December), for eligible addresses with City curbside service, up to six curbside collections per calendar year{c(0)}.</li><li>Each residence has an assigned collection day; look it up with the City's service lookup tool or the HTX App{c(0)}.</li><li>Set items out between 6:00 p.m. the Friday before and 7:00 a.m. on your collection day, just behind the curb line in front of your home, not in the street or on the sidewalk, and not under wires, signs or mailboxes or on top of meters or hydrants{c(0)}.</li><li>Eligibility: occupied residential units receiving City of Houston services; not available to multi-residential buildings with more than eight units{c(0)}.</li><li>For missed collections and other issues, contact 3-1-1 or submit a service request online; 311 service request status line: 832-394-1453 (Mon-Fri, 7:30 a.m. to 4:30 p.m.){c(1)}.</li></ul>"),
("Mattress bag requirements",lambda c:"<p>The City heavy trash page checked does not mention a bagging requirement for mattresses. Not verified.</p>"),
("Fees &amp; limits",lambda c:f"<ul><li>Maximum 8 cubic yards per set-out (about the size of a minivan){c(0)}.</li><li>Mixed piles: if authorized and unauthorized items are mixed, the whole pile may be refused{c(0)}.</li><li>Not accepted at the curb: everyday bagged garbage, electronics, paint and chemicals, dirt, roofing shingles, appliances with refrigerant unless tagged by a certified technician, and contractor debris{c(0)}.</li><li>The heavy trash page does not list a per-item fee for eligible residents{c(0)}.</li></ul>"),
("Drop-off between heavy trash months",lambda c:f"<ul><li>If you need to get rid of a mattress between heavy trash months or over the curbside limit, the City points residents to its Residential Drop-Off Centers{c(0)}, which it describes as a free service{c(2)}.</li><li>Locations: North, 9003 N Main 77022; Northwest, 14400 Sommermeyer 77041; Northeast, 5565 Kirkpatrick 77028; Southeast, 2240 Central Street 77017; South, 5100 Sunbeam 77033; Southwest, 10785 SW Freeway 77074{c(3)}.</li><li>Hours: Tuesday to Saturday, 9 a.m. to 6 p.m.; closed Sunday and Monday. Use is limited to four times per month (once per week); arrive at least 30 minutes before closing{c(3)}.</li><li>Mattresses are on the accepted bulk items list; furniture is limited to two large items{c(3)}.</li><li>Bring a current Texas-issued ID and a current City of Houston utility bill or lease with the same address{c(3)}.</li><li>Allowed vehicles: pickup trucks and small trailers up to 10 ft. Not allowed: U-Hauls, box trucks, Sprinter vans, contractor vehicles, dump trailers. You unload your own items{c(3)}.</li></ul>"),
("State disposal ban",lambda c:"<p>No Texas mattress disposal ban was found in the official sources checked; not verified.</p>"),
("Recycling &amp; retailer take-back",lambda c:BBM.format(c=c(4))+"<p>Retailer take-back: not verified from an official Houston source.</p>"),
],["https://www.houstontx.gov/solidwaste/heavytrash.html","https://www.houstontx.gov/solidwaste/","https://www.houstontx.gov/solidwaste/dropoff.html","https://www.houstontx.gov/solidwaste/depository.html",BBM_SRC],
["Whether mattresses must be bagged or wrapped for heavy trash.","Whether Texas has any mattress disposal ban.","Retailer take-back and private mattress recyclers in Houston.","Whether the Residential Drop-Off Centers charge anything for mattresses (the City calls them a free service; no fee found)."])

city("phoenix-az","Phoenix, AZ","Phoenix mattress and bulky item disposal: appointment-only bulk trash pickup (4 per year, 10 cubic yards), set-out rules, bed bug rule, and free monthly transfer station drop-off. Official City of Phoenix sources.",[
("Bulk trash pickup by appointment",lambda c:f"<ul><li>Phoenix collects bulk trash by appointment only; the old quarterly schedule ended and there is no quarterly schedule from 2025 on{c(0)}{c(1)}.</li><li>Schedule with the online tool on the City's Bulk Trash page or call 602-262-6251. Most areas have appointments within a couple of weeks, and you can book up to a year ahead{c(0)}.</li><li>Each customer can schedule up to four bulk trash collections per calendar year, booked at least 3 business days in advance{c(1)}.</li><li>Cancel no later than two business days before the appointment (link in your confirmation email, or call 602-262-6251); timely cancellations don't count against your four{c(0)}.</li><li>Check first whether your HOA or neighborhood already has a community-wide appointment{c(0)}.</li><li>Holiday blackouts: no appointments on Halloween, Thanksgiving, Christmas or New Year's Day, or the 7 days after each{c(0)}.</li></ul>"),
("Are mattresses accepted?",lambda c:f"<p>The City's Bulk Trash page says furniture is often considered bulk trash but does not name mattresses{c(0)}. The City's bulk trash map service description lists mattresses among items often considered bulk trash{c(2)}. An ordinance amending City Code Sec. 27-22 excludes mattresses or furniture known or suspected to be infested with bed bugs{c(3)}, but the current online City Code lists \"all mattresses or furniture\" as not acceptable for normal residential collection{c(4)}. Because the official sources disagree, call 602-262-6251 to confirm before setting a mattress out, and never put out a mattress with bed bugs.</p>"),
("How to set it out",lambda c:f"<ul><li>Place items no sooner than 7 days before your appointment{c(1)}{c(4)} and by 5:30 a.m. on the appointment date (collection starts at 6 a.m.){c(0)}{c(1)}.</li><li>One pile per household, curbside on the edge of your property parallel to the street, no more than 5 feet from the curb or front edge of the property, and at least 5 feet from any fixed object. Not on top of water meters, and not on the sidewalk or in the street{c(0)}{c(4)}.</li><li>Do not combine piles with neighbors; each household needs its own appointment{c(0)}.</li></ul>"),
("Mattress bag requirements",lambda c:"<p>The City pages checked do not mention a bagging requirement for mattresses. Not verified.</p>"),
("Fees &amp; limits",lambda c:f"<ul><li>Up to 10 cubic yards per appointment, roughly 17 ft x 4 ft x 4 ft{c(1)}{c(0)}.</li><li>Not accepted: household hazardous waste, tires, bricks, concrete, dirt and rocks, glass, loose yard waste, Bagster bags, more than 2 wooden pallets, and appliances that use refrigerants{c(0)}.</li><li>The City pages checked don't list a separate fee for a bulk trash appointment{c(0)}.</li></ul>"),
("Drop-off at a City transfer station",lambda c:f"<ul><li>City of Phoenix residential solid waste customers can drop off up to one ton each calendar month at no charge. Bring your City services (water) bill showing an active, current account and a photo ID with a matching name or address{c(5)}.</li><li>Above one ton, the gate rate is $55 per ton; other loads are $55 per ton with a $40 minimum. Cash and cards accepted; deposits are cash only{c(5)}.</li><li>Locations: North Gateway Transfer Station, 30205 N. Black Canyon Hwy., Phoenix 85085; 27th Avenue Transfer Station, 3060 S. 27th Ave., Phoenix 85009{c(5)}.</li><li>Hours: Monday to Friday 5:30 a.m. to 5 p.m., Saturday 6 a.m. to 3 p.m., closed Sunday and on listed holidays{c(5)}.</li><li>Loads must be secured; the unsecured load penalty is $20{c(5)}.</li><li>The transfer station page does not specifically mention mattresses; confirm at 602-262-6251{c(5)}.</li></ul>"),
("State disposal ban",lambda c:"<p>No Arizona mattress disposal ban was found in the official sources checked; not verified.</p>"),
("Recycling &amp; retailer take-back",lambda c:BBM.format(c=c(6))+"<p>Retailer take-back: not verified from an official Phoenix source.</p>"),
],["https://www.phoenix.gov/administration/departments/publicworks/residential-trash-recycling/bulk-trash-pickup.html","https://www.phoenix.gov/newsroom/public-works-news/3227.html","https://maps.phoenix.gov/pub/rest/services/Public/PublicWorksBulkTrash/MapServer","https://apps-secure.phoenix.gov/PublicRecordsSearch/Home/RenderPDF/?id=aWLzrgFr7ysHfGK2QYiOyLfuGzi4J18bCNV0g76x4aA%3D","https://phoenix.municipal.codes/CC/27-22","https://www.phoenix.gov/administration/departments/publicworks/about-us/transfer-stations.html",BBM_SRC],
["Whether mattresses are accepted in bulk trash pickup: City sources conflict (current City Code lists all mattresses and furniture as not acceptable; the City map service lists mattresses as bulk trash). Call 602-262-6251.","Whether transfer stations accept mattresses (not mentioned on the page checked).","Whether mattresses must be bagged or wrapped.","Whether Arizona has any mattress disposal ban.","Retailer take-back and private mattress recyclers in Phoenix."])

city("philadelphia-pa","Philadelphia, PA","Philadelphia mattress disposal: free curbside pickup with regular trash if sealed in a plastic mattress bag (2 large items per week), bulk appointment rules, six Sanitation Convenience Centers, and illegal dumping fines. Official City of Philadelphia sources.",[
("Curbside pickup with regular trash",lambda c:f"<ul><li>Mattresses and box springs are collected curbside as trash on your regular trash day; they count as compactible furniture (like sofas), limited to two items per week{c(0)}{c(5)}.</li><li>The separate Bulk Collection appointment program does <strong>not</strong> take mattresses; put a plastic-wrapped mattress out with regular trash instead{c(1)}{c(2)}. The City says it will keep collecting up to two large items per household on regular trash days, including mattresses wrapped in plastic{c(1)}.</li><li>Eligibility: City collection covers inhabited properties with six units or fewer (plus qualifying condos and co-ops); larger buildings and some business types must use private collection{c(0)}{c(5)}.</li><li>Look up your trash day on the City's collection day page or call Philly311 (dial 3-1-1, or 215-686-8686){c(0)}{c(9)}.</li></ul>"),
("Set-out times",lambda c:f"<ul><li>Outside Center City: set out between 7 p.m. the night before and 7 a.m. on collection day from April 1 to September 30, and between 5 p.m. the night before and 7 a.m. from October 1 to March 31{c(0)}.</li><li>Center City (Vine St. to Bainbridge St., Schuylkill River to Delaware River): 8 p.m. to 6 a.m. from April 1 to September 30, and 6 p.m. to 6 a.m. from October 1 to March 31{c(0)}.</li><li>Sources conflict on the season dates: the City's 2020 Streets Department regulations put the summer window at April 1 to October 31 and the winter window at November 1 to March 31{c(5)}. In October, setting out no earlier than 7 p.m. (by 7 a.m.) outside Center City, or no earlier than 8 p.m. (by 6 a.m.) in Center City, meets both versions.</li><li>Trash set out at other times counts as litter under the Philadelphia Code{c(5)}.</li></ul>"),
("Mattress bag requirements",lambda c:f"<p>For curbside pickup, mattresses and box springs must be bagged and sealed in plastic mattress bags{c(0)}; the regulations require them to be fully encased in a sealed plastic bag{c(5)}. The City's Bulk Collection site warns that unwrapped mattresses are not eligible for regular trash collection and are subject to fines{c(1)}. The City pages checked do not mention a separate bed bug rule.</p>"),
("Fees &amp; limits",lambda c:f"<ul><li>The City pages checked do not list a fee for putting a bagged mattress out with regular trash{c(0)}.</li><li>Limit: two compactible large items (such as mattresses, box springs or sofas) per week per property{c(0)}{c(5)}.</li><li>Violating the sanitation regulations carries a fine of $100 to $300, and each day a violation continues can count separately{c(5)}. The regulations list settlement amounts of $50 if paid within 10 days, rising to $75 and then $90 after reminder notices{c(5)}.</li><li>Trash set out over the limits is treated as litter and subject to penalties; for big cleanouts the regulations say to use a private hauler{c(5)}.</li></ul>"),
("Bulk Collection appointments (not for mattresses)",lambda c:f"<ul><li>Free appointment pickup for large items such as appliances (refrigerator doors removed), metal-frame furniture, large toys, flat-screen TVs, passenger car tires (rims removed, up to 4) and metal bathtubs{c(1)}{c(2)}.</li><li>Up to four items per appointment and one appointment per household per week. Open to residential households, including buildings with up to six units{c(1)}.</li><li>Schedule online at bulkcollection.phila.gov or through 311. Appointments are first-come, first-served and can be booked up to one month ahead; new dates open after midnight each day{c(1)}{c(2)}.</li><li>Set items at your normal collection point the evening before (no earlier than 5 p.m. in fall and winter, 7 p.m. in spring and summer), out by 7 a.m., and label them with the 4-letter pickup code from your confirmation email{c(1)}.</li><li>Furniture with a wooden frame goes out with regular trash, not bulk collection{c(1)}. Note that the 2024 launch announcement listed \"household furniture\" generally as eligible{c(2)}; the current program site limits it to metal-frame furniture{c(1)}.</li></ul>"),
("Drop-off at a Sanitation Convenience Center",lambda c:f"<ul><li>Philadelphia residents can drop off mattresses and box springs <strong>unwrapped</strong> at the City's six Sanitation Convenience Centers{c(3)}{c(0)}.</li><li>Hours: Monday to Saturday, 8 a.m. to 6 p.m.; closed on City holidays{c(3)}.</li><li>Bring proof that you live in Philadelphia. Regular household items can be dropped off once a day and oversized items once a week. Vehicles must weigh less than 6,000 pounds; commercial contractors and commercial loads are not allowed; no construction debris{c(3)}.</li><li>Also accepted: bulk and large metal items or appliances (two a day), up to four tires a day, up to six receptacles or 12 bags of trash, electronics, recycling and more{c(3)}.</li><li>Locations and phone numbers: Port Richmond, 3901 N Delaware Ave, 215-685-1358; West Philadelphia, 5100 Grays Ave, 215-685-2600; Strawberry Mansion, 2601 W Glenwood Ave, 215-685-3981; Southwest Philadelphia, 3033 S 63rd St, 215-685-4290; Northwest Philadelphia, 300 Domino Ln, 215-685-2502; Northeast Philadelphia, State Rd &amp; Ashburner St, 215-685-8072{c(4)}.</li><li>Sources conflict on bagging here: the current City pages say mattresses don't need to be bagged at a convenience center{c(3)}{c(0)}, but the 2020 regulations list mattresses as accepted only fully contained in a sealed plastic bag{c(5)}. Bagging it anyway works under both.</li></ul>"),
("Illegal dumping",lambda c:f"<ul><li>Dumping trash or debris on streets, public places or someone else's property is illegal, and each single large item, such as a mattress, counts as a separate offense{c(8)}. Anyone who hires someone to remove waste can be held liable for their dumping{c(8)}.</li><li>The City says fines are now up to $2,000 per item for dumping without a vehicle and up to $5,000 per item, per instance when a vehicle is used; cleanup costs can be recovered, and the Philadelphia Parking Authority can impound vehicles caught dumping{c(7)}.</li><li>If you see dumping happening, call 911 and don't confront anyone. To report it afterward, call 311 or use the City's online form with the location, a description of the people and vehicle (make, model, color, plate) and what was dumped{c(6)}.</li></ul>"),
("State disposal ban",lambda c:f"<p>No Pennsylvania mattress disposal ban was found in the official sources checked; not verified. Pennsylvania DEP tells residents to contact their trash hauler, or their county recycling coordinator, about disposing of bulky items{c(10)}.</p>"),
("Recycling &amp; retailer take-back",lambda c:BBM.format(c=c(11))+"<p>Retailer take-back and mattress recyclers in Philadelphia: not verified from an official Philadelphia source.</p>"),
],["https://www.phila.gov/departments/department-of-sanitation/about/rules-and-regulations/residential-trash-and-recycling-rules/","https://bulkcollection.phila.gov/","https://www.phila.gov/2024-09-23-city-of-philadelphia-residential-bulk-collection-program/","https://www.phila.gov/services/trash-recycling-city-upkeep/find-a-sanitation-convenience-center-to-drop-off-trash-or-recycling/","https://services.arcgis.com/fLeGjb7u4uXqeF9q/arcgis/rest/services/Sanitation_Convenience_Centers/FeatureServer/0/query?outFields=*&amp;where=1%3D1","https://www.phila.gov/media/20201015152607/Department-of-Streets-regulations.pdf","https://www.phila.gov/services/trash-recycling-city-upkeep/report-a-problem-with-trash-recycling-or-city-upkeep/report-illegal-dumping/","https://www.phila.gov/2025-12-29-illegal-dumping-task-force/","https://codelibrary.amlegal.com/codes/philadelphia/latest/philadelphia_pa/0-0-0-282458","https://www.phila.gov/2019-02-22-everything-you-need-to-know-about-litter-and-illegal-dumping/","https://www.pa.gov/agencies/dep/residents/recycling-and-disposal",BBM_SRC],
["Set-out season dates: the City website says the 5 p.m. winter window starts October 1; the 2020 regulations say November 1.","Whether mattresses must be bagged at Sanitation Convenience Centers: current City pages say no; the 2020 regulations say yes.","Whether the Sanitation Convenience Centers charge any fee (none listed on the page checked).","Which documents count as proof of residency at convenience centers (the page checked doesn't list them).","Whether Pennsylvania has any mattress disposal ban.","Any bed bug-specific rule beyond the plastic bag requirement.","Retailer take-back and private mattress recyclers in Philadelphia."])

